export function deflateCoordinate(o,r,l,g){for(let t=0,e=l.length;t<e;++t)o[r++]=l[t];return r}export function deflateCoordinates(o,r,l,g){for(let t=0,e=l.length;t<e;++t){const i=l[t];for(let u=0;u<g;++u)o[r++]=i[u]}return r}export function deflateCoordinatesArray(o,r,l,g,t){t=t||[];let e=0;for(let i=0,u=l.length;i<u;++i){const n=deflateCoordinates(o,r,l[i],g);t[e++]=n,r=n}return t.length=e,t}export function deflateMultiCoordinatesArray(o,r,l,g,t){t=t||[];let e=0;for(let i=0,u=l.length;i<u;++i){const n=deflateCoordinatesArray(o,r,l[i],g,t[e]);n.length===0&&(n[0]=r),t[e++]=n,r=n[n.length-1]}return t.length=e,t}
